import{_ as n,a0 as i,w as d,s as l,I as o,x as e,a1 as s,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情 | LCTT x X-CMD","titleTemplate":false,"description":"隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine","title":"隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情","tag":"202206","desc":""},"relativePath":"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine.md","filePath":"[post].md"}'),c={name:"202206/20220514 Hidden Features! 25 Fun Things You Can Do With DuckDuckGo Search Engine.md"};function h(m,a,u,g,f,k){const t=i("Link");return d(),l("div",null,[a[21]||(a[21]=o("h1",{id:"隱藏功能-在-duckduckgo-搜索引擎中-你可以做這-25-件有趣的事情",tabindex:"-1"},[e("隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情 "),o("a",{class:"header-anchor",href:"#隱藏功能-在-duckduckgo-搜索引擎中-你可以做這-25-件有趣的事情","aria-label":"Permalink to “隱藏功能！在 DuckDuckGo 搜索引擎中，你可以做這 25 件有趣的事情”"},"​")],-1)),a[22]||(a[22]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/11/142806ebr5xtzgcwcr5955.jpg",alt:""})],-1)),o("p",null,[a[1]||(a[1]=e("比起無處不在的 Google，",-1)),s(t,{href:"https://itsfoss.com/privacy-search-engines/"},{default:p(()=>[...a[0]||(a[0]=[e("有些搜索引擎替代品更加尊重隱私",-1)])]),_:1}),a[2]||(a[2]=e("，而 DuckDuckGo 就是其中之一。",-1))]),a[23]||(a[23]=r('<p>最近，這個搜索引擎有了很大的改進，搜索一般網頁十分順暢。在搜索本地地點方面，則還遠不及 Google。</p><p>不過，DuckDuckGo（簡稱為 DDG）有一些很酷的功能，大部分用户還沒注意到。如果你是一位 DDG 狂熱粉，你可能會喜歡用這些小技巧來提升你的搜索體驗。</p><h3 id="_1、跳轉到特定網頁" tabindex="-1">1、跳轉到特定網頁 <a class="header-anchor" href="#_1、跳轉到特定網頁" aria-label="Permalink to “1、跳轉到特定網頁”">​</a></h3><p>在你最喜歡的網站名稱前輸入 <code>!</code> 即可直接進入這個網站。則類似於 Google 的 “運氣不錯” 功能，但用 DDG 的話來説，這就叫 “歎號搜索”。</p><p>有一些網站有縮寫形式，開始輸入時便會提示。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/duckduckgo-bang-feature-800x449.png" alt="duckduckgo bang feature"></p><p>在網站名後面輸入搜索詞，就可以直接抵達那個網站的搜索結果處。</p><h3 id="_2、文本轉-ascii" tabindex="-1">2、文本轉 ASCII <a class="header-anchor" href="#_2、文本轉-ascii" aria-label="Permalink to “2、文本轉 ASCII”">​</a></h3>',8)),o("p",null,[a[4]||(a[4]=e("Figlet 是一個 ",-1)),s(t,{href:"https://itsfoss.com/funny-linux-commands/"},{default:p(()=>[...a[3]||(a[3]=[e("有趣的 Linux 命令",-1)])]),_:1}),a[5]||(a[5]=e("，可以將任意文本轉換為漂亮的 ASCII 畫格式。",-1))]),a[24]||(a[24]=r('<p>在任意搜索詞前輸入 <code>figlet</code>，就會顯示 ASCII 輸出。無需打開終端。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/figlet-800x272.png" alt="Figlet in DDG"></p><h3 id="_3、檢查社交媒體的狀態" tabindex="-1">3、檢查社交媒體的狀態 <a class="header-anchor" href="#_3、檢查社交媒體的狀態" aria-label="Permalink to “3、檢查社交媒體的狀態”">​</a></h3><p>在某個人的 Twitter 名前加上 <code>@</code>，就會顯示 TA 的狀態（關注者等）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/itsfoss-twitter-800x278.jpg" alt="Itsfoss Twitter"></p><h3 id="_4、生成強密碼" tabindex="-1">4、生成強密碼 <a class="header-anchor" href="#_4、生成強密碼" aria-label="Permalink to “4、生成強密碼”">​</a></h3><p>輸入 <code>password</code> 並加上需要的字符數，就可以生成一個獨特的強密碼。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/password-30-800x185.jpg" alt="Generating password in DuckDuckGo"></p><h3 id="_5、生成隨機密碼短語" tabindex="-1">5、生成隨機密碼短語 <a class="header-anchor" href="#_5、生成隨機密碼短語" aria-label="Permalink to “5、生成隨機密碼短語”">​</a></h3><p>輸入 <code>random passphrase</code> 可生成一段密碼短語，通常長度為 4 個詞。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-pqssphrase-800x179.png" alt="Random Passphrase"></p><h3 id="_6、獲取一份速查表" tabindex="-1">6、獲取一份速查表 <a class="header-anchor" href="#_6、獲取一份速查表" aria-label="Permalink to “6、獲取一份速查表”">​</a></h3><p>在需要看速查表的搜索詞後面，可輸入 <code>cheatsheet</code>。如果要搜索的東西有速查表，就會立即顯示在搜索頁面。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/vim-cheatsheet-800x367.png" alt="Vim Cheatsheet"></p><h3 id="_7、通過色碼獲取顏色" tabindex="-1">7、通過色碼獲取顏色 <a class="header-anchor" href="#_7、通過色碼獲取顏色" aria-label="Permalink to “7、通過色碼獲取顏色”">​</a></h3><p>輸入 <code>color</code> 並加上你想查的顏色的十六進制碼，便可顯示這個顏色。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/color-800x289.jpg" alt="Color"></p><h3 id="_8、生成隨機數" tabindex="-1">8、生成隨機數 <a class="header-anchor" href="#_8、生成隨機數" aria-label="Permalink to “8、生成隨機數”">​</a></h3><p>搜索 <code>random number</code> 會輸出一個 0 到 1 之間的隨機數。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-number-800x235.png" alt="Random Number"></p><p>你也可以指定需要的範圍。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/random-number-between-1-and-1000-800x244.png" alt="Random Number between 1 and 1000"></p><h3 id="_9、轉換為二進制等形式" tabindex="-1">9、轉換為二進制等形式 <a class="header-anchor" href="#_9、轉換為二進制等形式" aria-label="Permalink to “9、轉換為二進制等形式”">​</a></h3><p>輸入一個二進制數並加上 <code>binary</code>，可將其從二進制轉換為十進制。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/binary-800x184.png" alt="Binary to Decimal"></p><p>類似地，它也能用於十六進制和八進制，但我不清楚它們的處理邏輯。</p><h3 id="_10、尋找韻詞" tabindex="-1">10、尋找韻詞 <a class="header-anchor" href="#_10、尋找韻詞" aria-label="Permalink to “10、尋找韻詞”">​</a></h3><p>輸入 <code>what rhymes with</code> 並帶上要找同韻詞的詞語。作詩能力變強了，對吧？</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/What-rhymes-with-rain-800x257.png" alt="What rhymes with rain"></p><h3 id="_11、獲取拉馬努金數、圓周率等常數" tabindex="-1">11、獲取拉馬努金數、圓周率等常數 <a class="header-anchor" href="#_11、獲取拉馬努金數、圓周率等常數" aria-label="Permalink to “11、獲取拉馬努金數、圓周率等常數”">​</a></h3><p>輸入想獲取數值的常數名，便可在搜索結果中看到它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/ramanujan-number-800x238.png" alt="Ramanujan Number"></p><h3 id="_12、查詢現在誰在太空中" tabindex="-1">12、查詢現在誰在太空中 <a class="header-anchor" href="#_12、查詢現在誰在太空中" aria-label="Permalink to “12、查詢現在誰在太空中”">​</a></h3><p>輸入 <code>people in space</code> 獲取當前在太空中的人員名單。同時還會顯示他們在太空中居住的時間。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/people-in-space-800x313.jpg" alt="People in Space"></p><h3 id="_13、查詢網頁是否無法訪問" tabindex="-1">13、查詢網頁是否無法訪問 <a class="header-anchor" href="#_13、查詢網頁是否無法訪問" aria-label="Permalink to “13、查詢網頁是否無法訪問”">​</a></h3><p>如果你想知道某個網站是你無法訪問了，還是大家都無法訪問了，只需在搜索詞中輸入 <code>is xyz.com down</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/is-down-800x204.png" alt="Is down?"></p><h3 id="_14、獲取特定話題的名言" tabindex="-1">14、獲取特定話題的名言 <a class="header-anchor" href="#_14、獲取特定話題的名言" aria-label="Permalink to “14、獲取特定話題的名言”">​</a></h3><p>輸入一個詞並帶上 <code>quotes</code>，就會顯示與這個詞相關的名言。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/life-quotes-800x303.png" alt="Get quotes in DDG"></p><h3 id="_15、獲取佔位文本" tabindex="-1">15、獲取佔位文本 <a class="header-anchor" href="#_15、獲取佔位文本" aria-label="Permalink to “15、獲取佔位文本”">​</a></h3><p>搜索 <code>lorem ipsum</code> 就可以獲取 5 段佔位文本。對 Web 開發者應該會有用。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/lorem-ipsum-800x227.png" alt="Lorem ipsum"></p><h3 id="_16、獲取任意月份的日曆" tabindex="-1">16、獲取任意月份的日曆 <a class="header-anchor" href="#_16、獲取任意月份的日曆" aria-label="Permalink to “16、獲取任意月份的日曆”">​</a></h3><p>在年、月、日後面輸入 <code>calendar</code>，就會為你顯示該月份的交互式日曆。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/calendar-800x331.png" alt="Calendar"></p><h3 id="_17、生成二維碼" tabindex="-1">17、生成二維碼 <a class="header-anchor" href="#_17、生成二維碼" aria-label="Permalink to “17、生成二維碼”">​</a></h3><p>在文字、鏈接等後面輸入 <code>qr</code>，就會生成對應的二維碼。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/qrcode-800x255.png" alt="QRCode"></p><h3 id="_18、獲取一些-css-動畫" tabindex="-1">18、獲取一些 CSS 動畫 <a class="header-anchor" href="#_18、獲取一些-css-動畫" aria-label="Permalink to “18、獲取一些 CSS 動畫”">​</a></h3><p>搜索 <code>css animations</code> 以獲取一些 CSS 動畫例子。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/css-animations-800x385.jpg" alt="CSS Animations"></p><h3 id="_19、展開短鏈接" tabindex="-1">19、展開短鏈接 <a class="header-anchor" href="#_19、展開短鏈接" aria-label="Permalink to “19、展開短鏈接”">​</a></h3><p>如果有一個 Bitly 鏈接或其他短鏈接，但不確定它指向哪裏，不必再跳轉到充滿垃圾信息的網頁了，只需展開短鏈接，看看真正的網址。</p><p>在短鏈接後面輸入關鍵詞 <code>expand</code>，就會顯示真正的目標 URL。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/expand-shortened-link-ddg-800x209.png" alt="Expand Link"></p><h3 id="_20、獲取特殊字符的-html-代碼" tabindex="-1">20、獲取特殊字符的 HTML 代碼 <a class="header-anchor" href="#_20、獲取特殊字符的-html-代碼" aria-label="Permalink to “20、獲取特殊字符的 HTML 代碼”">​</a></h3><p>搜索 <code>html chars</code>，可以獲取一份很長的列表，上面有 HTML 實體及其描述，按下後會在結果中顯示更多信息。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/html-chars-800x174.png" alt="HTML Chars"></p><h3 id="_21、我用這東西幹啥" tabindex="-1">21、我用這東西幹啥？ <a class="header-anchor" href="#_21、我用這東西幹啥" aria-label="Permalink to “21、我用這東西幹啥？”">​</a></h3><p>這功能沒什麼用。如果你輸入 <code>why should I use this?</code> ，它就會在搜索結果頂部顯示 <code>cause it&#39;s awesome</code>。顯然，DuckDuckGo 在説他自己。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/why-should-i-use-this-800x160.png" alt="Why should I use this?"></p><h3 id="_22、轉換大小寫" tabindex="-1">22、轉換大小寫 <a class="header-anchor" href="#_22、轉換大小寫" aria-label="Permalink to “22、轉換大小寫”">​</a></h3><p>大小寫都可轉換。<code>lowercase &lt;大寫搜索詞&gt;</code> 就會顯示小寫的結果</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/lowercase-800x179.png" alt="Lowercase"></p><p><code>uppercase &lt;小寫搜索詞&gt;</code> 就會顯示大寫的結果。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/uppercase-800x185.png" alt="Uppercase"></p><h3 id="_23、編碼-url" tabindex="-1">23、編碼 URL <a class="header-anchor" href="#_23、編碼-url" aria-label="Permalink to “23、編碼 URL”">​</a></h3><p>搜索 <code>encode</code> 並加上 URL，就會給出編碼後的結果</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/url-encode-800x177.png" alt="URL Encode"></p><h3 id="_24、motherboard" tabindex="-1">24、Motherboard <a class="header-anchor" href="#_24、motherboard" aria-label="Permalink to “24、Motherboard”">​</a></h3><p>搜索 <code>Motherboard</code> 就會看見左側的 DuckDuckGo 的 logo 變了。它會顯示選好的幾個隨機 logo。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/motherboard.png" alt="Motherboard"></p><h3 id="_25、獲取-html-色碼" tabindex="-1">25、獲取 HTML 色碼 <a class="header-anchor" href="#_25、獲取-html-色碼" aria-label="Permalink to “25、獲取 HTML 色碼”">​</a></h3><p>搜索 <code>color codes</code> 便可獲得一份顏色表。一樣，這個功能多為 Web 開發者和設計師所用。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/color-codes-800x554.png" alt="Color Codes"></p><h3 id="還有很多別的···" tabindex="-1">還有很多別的··· <a class="header-anchor" href="#還有很多別的···" aria-label="Permalink to “還有很多別的···”">​</a></h3><p>我的夥伴 Sreenath 想到本貼的主意。他説 DuckDuckGo 中還有許多 “彩蛋”，我覺得沒錯。但全部列出來有諸多不便。</p><p>如果你知道更多這樣有趣的 DDG 搜索功能，請在評論中分享。如果你又發現了你喜歡的搜索功能，也提出來吧。</p><hr>',81)),o("p",null,[a[7]||(a[7]=e("via: ",-1)),s(t,{href:"https://itsfoss.com/duckduckgo-easter-eggs/"},{default:p(()=>[...a[6]||(a[6]=[e("https://itsfoss.com/duckduckgo-easter-eggs/",-1)])]),_:1})]),o("p",null,[a[12]||(a[12]=e("作者：",-1)),s(t,{href:"https://itsfoss.com/author/sreenath/"},{default:p(()=>[...a[8]||(a[8]=[e("sreenath",-1)])]),_:1}),a[13]||(a[13]=e(" 選題：",-1)),s(t,{href:"https://github.com/lkxed"},{default:p(()=>[...a[9]||(a[9]=[e("lkxed",-1)])]),_:1}),a[14]||(a[14]=e(" 譯者：",-1)),s(t,{href:"https://github.com/TravinDreek"},{default:p(()=>[...a[10]||(a[10]=[e("Peaksol",-1)])]),_:1}),a[15]||(a[15]=e(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:p(()=>[...a[11]||(a[11]=[e("wxy",-1)])]),_:1})]),o("p",null,[a[18]||(a[18]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[16]||(a[16]=[e("LCTT",-1)])]),_:1}),a[19]||(a[19]=e(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:p(()=>[...a[17]||(a[17]=[e("Linux中國",-1)])]),_:1}),a[20]||(a[20]=e(" 榮譽推出",-1))])])}const D=n(c,[["render",h]]);export{_ as __pageData,D as default};
